import type { ComponentPropsWithRef, HTMLAttributes, ReactNode } from 'react';
import '../theme.css';
import './surface.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface ShellProps extends HTMLAttributes<HTMLElement> {
  /** 'div' by default. Use 'section' with aria-labelledby when the Shell is a page region. */
  as?: 'div' | 'section' | 'article' | 'aside';
}

/** The framed outer layer. Put a ShellHeader and a Panel inside it. */
export function Shell({ as: Tag = 'div', className, ...rest }: ShellProps) {
  return <Tag className={cx('ws-shell', className)} {...rest} />;
}

export interface ShellHeaderProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title: ReactNode;
  /** Use a heading level that fits the page outline. */
  titleAs?: 'p' | 'h2' | 'h3' | 'h4';
  titleId?: string;
  meta?: ReactNode;
  actions?: ReactNode;
}

/** Title row in the Shell padding. Extra children (a search field, filters) go below the row. */
export function ShellHeader({ title, titleAs: Title = 'p', titleId, meta, actions, className, children, ...rest }: ShellHeaderProps) {
  return (
    <div className={cx('ws-shell-header', className)} {...rest}>
      <div className="ws-shell-header__row">
        <Title className="ws-shell-header__title" id={titleId}>
          {title}
        </Title>
        {meta !== undefined && meta !== null ? <span className="ws-shell-header__meta">{meta}</span> : null}
        {actions ? <div className="ws-shell-header__actions">{actions}</div> : null}
      </div>
      {children}
    </div>
  );
}

/** The white content layer inside a Shell. `ref` reaches the div, for example to hold focus while content reloads. */
export function Panel({ className, ...rest }: ComponentPropsWithRef<'div'>) {
  return <div className={cx('ws-panel', className)} {...rest} />;
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

/* Shell is the tinted outer layer; headers sit in its padding. Panel is the
   white content layer inside it. The tone step frames the Shell, so one line
   around the Panel is the only edge a component draws. */

.ws-shell {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: var(--ws-space-1);
  border-radius: var(--ws-radius-xl);
  background: var(--ws-color-surface);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
  font-weight: var(--ws-weight-regular);
  line-height: var(--ws-leading);
  letter-spacing: 0;
  text-align: start;
}

.ws-shell-header {
  box-sizing: border-box;
  display: grid;
  gap: var(--ws-space-3);
  /* Text lines up with content inside the Panel (Panel adds a 1px border). */
  padding: var(--ws-space-3) calc(var(--ws-space-4) + 1px);
}

.ws-shell-header__row {
  display: flex;
  align-items: center;
  gap: var(--ws-space-3);
  min-height: 24px;
}

.ws-shell-header__title {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  color: var(--ws-color-text);
  font-size: var(--ws-text-md);
  font-weight: var(--ws-weight-semibold);
  line-height: var(--ws-leading-tight);
  letter-spacing: var(--ws-tracking-title);
  overflow-wrap: anywhere;
}

.ws-shell-header__meta {
  flex: none;
  color: var(--ws-color-text-muted);
  font-size: var(--ws-text-sm);
  line-height: var(--ws-leading-tight);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ws-shell-header__actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--ws-space-2);
}

/* Panel also sets its own type, so it reads the same outside a Shell. */
.ws-panel {
  box-sizing: border-box;
  min-width: 0;
  border: 1px solid var(--ws-color-line);
  border-radius: var(--ws-radius-lg);
  background: var(--ws-color-panel);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
  line-height: var(--ws-leading);
  text-align: start;
  overflow: hidden;
}
